function Read-Hidden([string]$Label){$s=Read-Host $Label -AsSecureString;try{if($s.Length-eq 0){throw 'Empty value.'};$p=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($s);try{[Runtime.InteropServices.Marshal]::PtrToStringBSTR($p)}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($p)}}finally{$s.Dispose()}}
function Login([string]$Email,[string]$Password){$q=[Net.Http.HttpRequestMessage]::new([Net.Http.HttpMethod]::Post,'/auth/v1/token?grant_type=password');try{$q.Content=[Net.Http.StringContent]::new((ConvertTo-Json @{email=$Email;password=$Password}-Compress),[Text.Encoding]::UTF8,'application/json');$x=$script:client.SendAsync($q).GetAwaiter().GetResult();try{if(-not$x.IsSuccessStatusCode){throw "Login HTTP $([int]$x.StatusCode)"};$b=$x.Content.ReadAsStringAsync().GetAwaiter().GetResult()|ConvertFrom-Json;[pscustomobject]@{Id=[guid]$b.user.id;Token=[string]$b.access_token}}finally{$x.Dispose()}}finally{$q.Dispose()}}
function SendAs([string]$Token,[string]$Action,[object]$Request){$q=[Net.Http.HttpRequestMessage]::new([Net.Http.HttpMethod]::Post,'/rest/v1/rpc/task_dispatch');try{$q.Headers.Add('Content-Profile','reivro_checks_api');$q.Headers.Authorization=[Net.Http.Headers.AuthenticationHeaderValue]::new('Bearer',$Token);$q.Content=[Net.Http.StringContent]::new((ConvertTo-Json @{action=$Action;request=$Request}-Depth 30 -Compress),[Text.Encoding]::UTF8,'application/json');$x=$script:client.SendAsync($q).GetAwaiter().GetResult();try{[pscustomobject]@{Status=[int]$x.StatusCode;Body=$x.Content.ReadAsStringAsync().GetAwaiter().GetResult()}}finally{$x.Dispose()}}finally{$q.Dispose()}}
function PsqlJson([string]$File,[hashtable]$Extra){$op=[Environment]::GetEnvironmentVariable('PGPASSWORD','Process');$oc=[Environment]::GetEnvironmentVariable('PGSSLROOTCERT','Process');try{$env:PGPASSWORD=$script:dbPassword;$env:PGSSLROOTCERT=$script:ca;$a=@('-X','-w','-qAt','-v','ON_ERROR_STOP=1','-d','host=aws-1-us-west-1.pooler.supabase.com port=5432 user=postgres.lbklqqqbmeyseeccdqog dbname=postgres sslmode=verify-full','-v',"repository_id=$($script:planDoc.repository_id)",'-v',"original_submission_id=$($script:planDoc.submission_id)",'-v',"base_sha=$($script:planDoc.base_sha)",'-v',"head_sha=$($script:planDoc.head_sha)",'-v',"new_contract_id=$script:contractId",'-v',"new_submission_id=$script:submissionId");foreach($k in $Extra.Keys){$a+=@('-v',"$k=$($Extra[$k])")};$a+=@('-f',$File);$o=&$script:psql @a;if($LASTEXITCODE-ne 0){throw "psql exited $LASTEXITCODE"};$z=@($o|Where-Object{$_-match'^\{'});if($z.Count-ne 1){throw 'Expected one reconciliation record.'};$z[0]|ConvertFrom-Json}finally{if($null-eq$op){Remove-Item Env:PGPASSWORD -ErrorAction SilentlyContinue}else{$env:PGPASSWORD=$op};if($null-eq$oc){Remove-Item Env:PGSSLROOTCERT -ErrorAction SilentlyContinue}else{$env:PGSSLROOTCERT=$oc}}}
$client=$handler=$key=$dbPassword=$reviewerEmail=$reviewerPassword=$agentEmail=$agentPassword=$workerEmail=$workerPassword=$approval=$null;$reviewer=$agent=$worker=$null;$stage='initialization';$writeStarted=$false
try{
 $shared=Join-Path $PSScriptRoot 'ReivroFinalPlanValidation.ps1';$pre=Join-Path $PSScriptRoot 'preflight_staging_renew_fail_fixture.sql';$checkpoint=Join-Path $PSScriptRoot 'checkpoint_staging_renew_fail_fixture.sql';$mid=Join-Path $PSScriptRoot 'midcheck_staging_renew_fail_fixture.sql';$post=Join-Path $PSScriptRoot 'postcheck_staging_renew_fail_fixture.sql';$reconcile=Join-Path $PSScriptRoot 'reconcile_staging_renew_fail_fixture.sql';$cert=Join-Path $HOME 'Downloads\prod-ca-2021.crt'
 foreach($p in @($PlanPath,$shared,$pre,$checkpoint,$mid,$post,$reconcile,$cert)){if(-not(Test-Path -LiteralPath $p -PathType Leaf)){throw 'Required local input is missing.'}}
