 $psql=(Resolve-Path (Join-Path $PgBin 'psql.exe')).Path;if((&$psql --version)-notmatch'PostgreSQL\)\s+19(?:\.\d+)?(?:\s|$)'){throw 'PostgreSQL 19 required.'};$git=(Get-Command git -CommandType Application).Source;$ca=(Resolve-Path $cert).Path
 $origin=(&$git -C $Repository remote get-url origin).Trim();if($origin-cnotmatch'(?i)(?:github\.com[/:])sovereis/REIVRO(?:\.git)?$'){throw 'Unexpected Git origin.'};&$git -C $Repository merge-base --is-ancestor $planDoc.base_sha $planDoc.head_sha;if($LASTEXITCODE-ne 0){throw 'Invalid Git ancestry.'};&$git -C $Repository cat-file -e "$($planDoc.head_sha):guide.md";if($LASTEXITCODE-ne 0){throw 'guide.md absent.'}
 $receipt=Join-Path (Split-Path -Parent $PlanPath) 'renew-fail-security-gate-receipt.json';if(Test-Path $receipt){throw 'Private security gate receipt already exists; reconcile before retry.'};$contractId=[guid]::NewGuid();$submissionId=[guid]::NewGuid()
