 $approval=Read-Host 'Type STAGING-RENEW-FAIL-SECURITY-GATE-APPROVED';if($approval-cne'STAGING-RENEW-FAIL-SECURITY-GATE-APPROVED'){throw 'Gate not locally confirmed.'}
 [ordered]@{state='PLANNED';staging_ref='lbklqqqbmeyseeccdqog';contract_id=$contractId;submission_id=$submissionId;baseline_events=21}|ConvertTo-Json|Set-Content -LiteralPath $receipt -Encoding UTF8
 $doc=$scope.contract_document;$newDigest=[string]$scope.contract_digest;$baseRequest=@{repository_id=[long]$planDoc.repository_id;id=$contractId.ToString()}
