 $stage='submit';$x=SendAs $agent.Token 'submit' (@{repository_id=[long]$planDoc.repository_id;id=$submissionId.ToString();contract_id=$contractId.ToString();version=1;digest=$newDigest;head_sha=[string]$planDoc.head_sha});if($x.Status -lt 200 -or $x.Status -ge 300){throw "Submit HTTP $($x.Status)"};$saved=PsqlJson $checkpoint @{new_digest=$newDigest;expected_events=23};if(-not [bool]$saved.all_checks_pass){throw 'Submission checkpoint failed.'}
 # No prompts occur after this point. The 60-second lease starts at claim.
