 $stage='claim';$x=SendAs $worker.Token 'claim' $claimRequest;if($x.Status -lt 200 -or $x.Status -ge 300){throw "Claim HTTP $($x.Status)"};$claim=$x.Body|ConvertFrom-Json;if($claim.state -cne 'running' -or [int]$claim.fence -ne 1){throw 'Unexpected claim receipt.'}
 $renew=@{repository_id=[long]$planDoc.repository_id;installation_id=[long]$scope.installation_id;id=$submissionId.ToString();run_id=[string]$claim.run_id;attempt_id=[string]$claim.attempt_id;fence=1}
 $stage='renew';$x=SendAs $worker.Token 'renew' $renew;if($x.Status -lt 200 -or $x.Status -ge 300){throw "Renew HTTP $($x.Status)"}
 $stage='negative wrong attempt';$bad=$renew.Clone();$bad.attempt_id=[guid]::NewGuid().ToString();$x=SendAs $worker.Token 'renew' $bad;if($x.Status -lt 400 -or $x.Status -ge 500){throw 'Wrong attempt was not denied.'}
 $stage='negative wrong fence';$bad=$renew.Clone();$bad.fence=2;$x=SendAs $worker.Token 'renew' $bad;if($x.Status -lt 400 -or $x.Status -ge 500){throw 'Wrong fence was not denied.'}
 $stage='negative reconciliation';$saved=PsqlJson $mid @{run_id=$claim.run_id;worker_id=$worker.Id;attempt_id=$claim.attempt_id};if(-not [bool]$saved.all_checks_pass){throw 'Negative probes changed durable state.'}
 $stage='fail retryable';$x=SendAs $worker.Token 'fail' $renew;if($x.Status -lt 200 -or $x.Status -ge 300){throw "Fail HTTP $($x.Status)"};$failed=$x.Body|ConvertFrom-Json;if($failed.state -cne 'retryable'){throw 'Fail did not become retryable.'}
 $stage='postcheck';$saved=PsqlJson $post @{run_id=$claim.run_id;worker_id=$worker.Id};if(-not [bool]$saved.all_checks_pass){throw 'Final retryable state failed reconciliation.'}
