 Write-Output 'PASS renew valid';Write-Output 'PASS wrong attempt and fence denied without durable effects';Write-Output 'PASS fail retryable and first completed run preserved';Write-Output 'RENEW_FAIL_SECURITY_GATE_RETRYABLE_PASS'
}catch{[Console]::Error.WriteLine("FAIL $stage");if($writeStarted){[Console]::Error.WriteLine('DO NOT RETRY. READ-ONLY RECONCILIATION FOLLOWS.');try{$r=PsqlJson $reconcile @{};[Console]::Error.WriteLine(('RECONCILIATION '+(ConvertTo-Json $r -Depth 20 -Compress)))}catch{[Console]::Error.WriteLine('READ-ONLY RECONCILIATION FAILED; stop and preserve evidence.')}};exit 1}finally{$key=$dbPassword=$reviewerEmail=$reviewerPassword=$agentEmail=$agentPassword=$workerEmail=$workerPassword=$approval=$null;if($null-ne$reviewer){$reviewer.Token=$null};if($null-ne$agent){$agent.Token=$null};if($null-ne$worker){$worker.Token=$null};Remove-Item Env:PGPASSWORD,Env:PGSSLROOTCERT -ErrorAction SilentlyContinue;if($null-ne$client){$client.Dispose()}elseif($null-ne$handler){$handler.Dispose()}}
